class RotatedBillion:
    """A billion distinct numbers: the even numbers 0, 2, 4, ... sorted, then rotated so that position 0 holds 2 * shift.
    It supports only len() and nums[i], and counts every look."""
    size = 1_000_000_000

    def __init__(self, shift):
        self.shift = shift
        self.looks = 0

    def __len__(self):
        return self.size

    def __getitem__(self, i):
        if not isinstance(i, int):
            raise TypeError("a sequence of a billion numbers can only be read one position at a time, nums[i] (no slices)")
        self.looks += 1
        if self.looks > 500:
            raise AssertionError("looked at more than 500 elements of a list of a billion numbers: this search needs about 30 steps")
        if i < 0:
            i += self.size
        if not 0 <= i < self.size:
            raise IndexError("list index out of range")
        return 2 * ((i + self.shift) % self.size)
def in_a_billion(shift, value):
    """search_rotated on the billion numbers that start at 2 * shift."""
    return search_rotated(RotatedBillion(shift), value)
